import React, { useState, useEffect } from 'react';
import { getClassDefinition } from '../data/classDefinitions';
import { ClassDefinition } from '../types/ClassFramework';

interface FloatingTooltipProps {
  mousePosition: { x: number; y: number };
}

const FloatingTooltip: React.FC<FloatingTooltipProps> = ({ mousePosition }) => {
  const [tooltipContent, setTooltipContent] = useState<ClassDefinition | null>(null);
  const [hoveredElement, setHoveredElement] = useState<HTMLElement | null>(null);

  useEffect(() => {
    const handleMouseOver = (event: Event) => {
      const target = event.target as HTMLElement;
      // Find the closest parent element with data-class-id, or use the target itself
      const elementWithClass = target.closest('[data-class-id]') as HTMLElement;
      const classId = elementWithClass?.getAttribute('data-class-id');

      if (classId) {
        // Get class info from the proper class framework
        const classInfo = getClassDefinition(classId);
        if (classInfo) {
          setTooltipContent(classInfo);

          // Use the actual hovered element (target) for better positioning
          // This ensures we avoid overlap with the specific element being hovered
          setHoveredElement(target);
        }
      }
    };

    const handleMouseOut = () => {
      setTooltipContent(null);
      setHoveredElement(null);
    };

    const handleMouseMove = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      // Check if mouse is over simulation controls (but not the tooltip itself)
      const isOverSimulationControls = target.closest('.simulation-controls') !== null;
      const isOverTooltip = target.closest('[data-tooltip="true"]') !== null;

      if (isOverSimulationControls && !isOverTooltip) {
        setTooltipContent(null);
        setHoveredElement(null);
      }
    };

    // Function to add event listeners
    const addEventListeners = () => {
      const elementsWithClasses = document.querySelectorAll('[data-class-id]');

      elementsWithClasses.forEach(element => {
        element.addEventListener('mouseover', handleMouseOver);
        element.addEventListener('mouseout', handleMouseOut);
      });
    };

    // Add listeners immediately
    addEventListeners();

    // Also add listeners periodically to catch dynamically created elements
    const interval = setInterval(addEventListeners, 1000);

    // Add global mouse move listener to detect simulation controls
    document.addEventListener('mousemove', handleMouseMove);

    return () => {
      clearInterval(interval);
      const elementsWithClasses = document.querySelectorAll('[data-class-id]');
      elementsWithClasses.forEach(element => {
        element.removeEventListener('mouseover', handleMouseOver);
        element.removeEventListener('mouseout', handleMouseOut);
      });
      document.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  // Calculate smart positioning to keep tooltip on screen and avoid element overlap
  const calculatePosition = () => {
    const tooltipWidth = 400; // Increased for more content
    const tooltipHeight = 200; // Increased for more content
    const padding = 20; // Padding from screen edges
    const elementPadding = 15; // Increased padding from hovered element

    // Start with mouse position (bottom right)
    let left = mousePosition.x + 20;
    let top = mousePosition.y + 20;

    // If we have a hovered element, try to avoid overlapping with it
    if (hoveredElement) {
      const elementRect = hoveredElement.getBoundingClientRect();

      // Calculate tooltip boundaries
      const tooltipRight = left + tooltipWidth;
      const tooltipBottom = top + tooltipHeight;

      // Check for horizontal overlap
      const horizontalOverlap = left < elementRect.right + elementPadding && tooltipRight > elementRect.left - elementPadding;

      // Check for vertical overlap
      const verticalOverlap = top < elementRect.bottom + elementPadding && tooltipBottom > elementRect.top - elementPadding;

      // If both horizontal and vertical overlap, try different positions
      if (horizontalOverlap && verticalOverlap) {
        // Try positioning to the left of the element
        if (mousePosition.x - tooltipWidth - elementPadding > padding) {
          left = mousePosition.x - tooltipWidth - elementPadding;
        }
        // If left doesn't work, try above the element
        else if (mousePosition.y - tooltipHeight - elementPadding > padding) {
          top = mousePosition.y - tooltipHeight - elementPadding;
        }
        // If above doesn't work, try to the right
        else if (elementRect.right + elementPadding + tooltipWidth < window.innerWidth - padding) {
          left = elementRect.right + elementPadding;
        }
        // If right doesn't work, try below
        else if (elementRect.bottom + elementPadding + tooltipHeight < window.innerHeight - padding) {
          top = elementRect.bottom + elementPadding;
        }
      }
      // If only horizontal overlap, try left or right
      else if (horizontalOverlap) {
        if (mousePosition.x - tooltipWidth - elementPadding > padding) {
          left = mousePosition.x - tooltipWidth - elementPadding;
        } else if (elementRect.right + elementPadding + tooltipWidth < window.innerWidth - padding) {
          left = elementRect.right + elementPadding;
        }
      }
      // If only vertical overlap, try above or below
      else if (verticalOverlap) {
        if (mousePosition.y - tooltipHeight - elementPadding > padding) {
          top = mousePosition.y - tooltipHeight - elementPadding;
        } else if (elementRect.bottom + elementPadding + tooltipHeight < window.innerHeight - padding) {
          top = elementRect.bottom + elementPadding;
        }
      }
    }

    // Check right edge
    if (left + tooltipWidth > window.innerWidth - padding) {
      left = mousePosition.x - tooltipWidth - 20;
    }

    // Check left edge
    if (left < padding) {
      left = padding;
    }

    // Check bottom edge
    if (top + tooltipHeight > window.innerHeight - padding) {
      top = mousePosition.y - tooltipHeight - 20;
    }

    // Check top edge
    if (top < padding) {
      top = padding;
    }

    return { left, top };
  };

  const position = calculatePosition();

  // Only show tooltip when there's content
  if (!tooltipContent) {
    return null;
  }

  // Get the first note for display (most classes have one main note)
  const mainNote = tooltipContent.notes[0];

  // Get severity color
  const getSeverityColor = (severity?: string) => {
    switch (severity) {
      case 'danger': return '#ef4444';
      case 'warning': return '#f59e0b';
      case 'success': return '#10b981';
      case 'info': return '#3b82f6';
      default: return '#6b7280';
    }
  };

  return (
    <div
      className="floating-tooltip"
      data-tooltip="true"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: '#2d2d2d',
        border: '1px solid #555',
        borderRadius: '6px',
        padding: '12px 16px',
        zIndex: 99999,
        boxShadow: '0 4px 12px rgba(0,0,0,0.4)',
        backdropFilter: 'blur(10px)',
        minWidth: '280px',
        maxWidth: '400px',
        cursor: 'default',
        userSelect: 'auto',
        transition: 'box-shadow 0.2s',
        pointerEvents: 'auto',
        isolation: 'isolate',
        overflow: 'visible'
      }}
    >
      <div style={{ 
        fontSize: '14px', 
        color: '#e0e0e0',
        textAlign: 'left',
        lineHeight: '1.4'
      }}>
        {/* Header with icon and title */}
        <div style={{ 
          display: 'flex',
          alignItems: 'center',
          marginBottom: '8px',
          gap: '8px'
        }}>
          <span style={{ fontSize: '16px' }}>{tooltipContent.icon}</span>
          <div style={{ 
            fontSize: '15px', 
            color: '#ffffff', 
            fontWeight: '600',
            pointerEvents: 'none'
          }}>
            {tooltipContent.name}
          </div>
        </div>

        {/* Category and Severity */}
        <div style={{ 
          display: 'flex',
          alignItems: 'center',
          gap: '12px',
          marginBottom: '8px',
          fontSize: '12px'
        }}>
          <span style={{ 
            color: '#b0b0b0',
            background: '#1a1a1a',
            padding: '2px 6px',
            borderRadius: '3px'
          }}>
            {mainNote?.category || 'Scareware'}
          </span>
          {mainNote?.severity && (
            <span style={{ 
              color: getSeverityColor(mainNote.severity),
              fontWeight: '500',
              display: 'flex',
              alignItems: 'center'
            }}>
              {mainNote.severity.toUpperCase()}
            </span>
          )}
        </div>

        {/* Description */}
        <div style={{ 
          marginBottom: '10px',
          color: '#b0b0b0',
          fontSize: '13px'
        }}>
          {mainNote?.description || tooltipContent.description}
        </div>

        {/* Examples */}
        {mainNote?.examples && mainNote.examples.length > 0 && (
          <div style={{ marginBottom: '8px' }}>
            <div style={{ 
              fontSize: '12px', 
              color: '#d0d0d0',
              fontWeight: '500',
              marginBottom: '4px'
            }}>
              Examples:
            </div>
            <ul style={{ 
              margin: '0',
              paddingLeft: '16px',
              fontSize: '12px',
              color: '#a0a0a0'
            }}>
              {mainNote.examples.slice(0, 2).map((example, index) => (
                <li key={index} style={{ marginBottom: '2px' }}>{example}</li>
              ))}
            </ul>
          </div>
        )}

        {/* Tips */}
        {mainNote?.tips && mainNote.tips.length > 0 && (
          <div style={{ marginBottom: '8px' }}>
            <div style={{ 
              fontSize: '12px', 
              color: '#10b981',
              fontWeight: '500',
              marginBottom: '4px'
            }}>
              Safety Tips:
            </div>
            <ul style={{ 
              margin: '0',
              paddingLeft: '16px',
              fontSize: '12px',
              color: '#a0a0a0'
            }}>
              {mainNote.tips.slice(0, 2).map((tip, index) => (
                <li key={index} style={{ marginBottom: '2px' }}>{tip}</li>
              ))}
            </ul>
          </div>
        )}

        {/* Context box */}
        <div style={{ 
          fontSize: '12px', 
          color: '#d0d0d0',
          fontStyle: 'italic',
          background: '#1a1a1a',
          border: '1px solid #444',
          borderRadius: '4px',
          padding: '8px 10px',
          marginTop: '8px'
        }}>
          This element is part of the scareware simulation to demonstrate how {tooltipContent.name.toLowerCase()} tactics work.
        </div>
      </div>
    </div>
  );
};

export default FloatingTooltip;
